package com.tekwatt.admin.controller;import com.fasterxml.jackson.databind.JsonNode;import com.tekwatt.admin.dto.*;import com.tekwatt.admin.service.AdminService;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/admin")public class AdminController{private final AdminService service;public AdminController(AdminService service){this.service=service;}@GetMapping("/tenants")JsonNode tenants(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.tenants(page,size);}@GetMapping("/users")JsonNode users(@RequestParam UUID tenantId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.users(tenantId,page,size);}@GetMapping("/chargers")JsonNode chargers(@RequestParam UUID tenantId){return service.chargers(tenantId);}@GetMapping("/ocpp-connections")JsonNode connections(){return service.connections();}@PostMapping("/actions")@ResponseStatus(HttpStatus.CREATED)AdminActionResponse execute(@Valid@RequestBody AdminActionRequest request){return service.execute(request);}@GetMapping("/actions/{id}")AdminActionResponse get(@PathVariable UUID id){return service.getAction(id);}@GetMapping("/actions")Page<AdminActionResponse>list(@RequestParam UUID actorId,Pageable pageable){return service.listActions(actorId,pageable);}}
